// 類別圖對應的 C# 程式碼範例
// 關係：Order ◆→ OrderItem（組合）；Customer 1──* Order（關聯）

public class Customer
{
    public int    CustomerId { get; set; }
    public string Name       { get; set; }
    public List<Order> Orders { get; set; } = new List<Order>();
}

public class Order
{
    public int      OrderId  { get; set; }
    public DateTime OrderDate { get; set; }
    public int      CustomerId { get; set; }

    // 組合關係：OrderItem 屬於 Order，生命週期相同
    private List<OrderItem> _items = new List<OrderItem>();
    public IReadOnlyList<OrderItem> Items => _items;

    public void AddItem(int productId, int qty, decimal price)
        => _items.Add(new OrderItem(productId, qty, price));
}

public class OrderItem
{
    public int     ProductId { get; }
    public int     Qty       { get; }
    public decimal UnitPrice { get; }

    // 只能由 Order 建立（體現組合關係）
    internal OrderItem(int productId, int qty, decimal price)
    {
        ProductId = productId;
        Qty       = qty;
        UnitPrice = price;
    }
}

