// ┌──────────────────┐
// │  {abstract}Shape │
// ├──────────────────┤
// │ + Color: string  │
// ├──────────────────┤
// │ + Area(): double │ {abstract}
// └────────┬─────────┘
//          △ (繼承，空心三角)
//    ┌─────┴──────┐
//    │            │
// ┌──┴───┐  ┌────┴──────┐
// │Circle│  │ Rectangle │
// ├──────┤  ├───────────┤
// │+Radius│ │+Width     │
// │:double│ │+Height    │
// ├──────┤  │:double    │
// │+Area()│ ├───────────┤
// └──────┘  │+Area()    │
//           └───────────┘

// 對應 C# 程式碼：
public abstract class Shape
{
    public string Color { get; set; }
    public abstract double Area();
}

public class Circle : Shape
{
    public double Radius { get; set; }
    public override double Area() => Math.PI * Radius * Radius;
}

public class Rectangle : Shape
{
    public double Width  { get; set; }
    public double Height { get; set; }
    public override double Area() => Width * Height;
}

// 組合（Composition）：強擁有，部件不能脫離整體獨立存在
// 例子：人體（Body）與心臟（Heart）
// Heart 的生命週期與 Body 相同

public class Heart
{
    public int BPM { get; set; }
}

public class Body
{
    // 組合：Heart 在 Body 建構時建立，Body 消滅時 Heart 也消滅
    private readonly Heart _heart = new Heart { BPM = 72 };
    public int HeartRate => _heart.BPM;
}

// ─────────────────────────────────────────

// 聚合（Aggregation）：弱擁有，部件可獨立存在
// 例子：球隊（Team）與球員（Player）
// Player 可以不屬於任何 Team，也可以轉隊

public class Player
{
    public string Name { get; set; }
}

public class Team
{
    private List<Player> _players = new List<Player>();

    // 聚合：Player 從外部傳入，Team 消失後 Player 仍存在
    public void AddPlayer(Player p) => _players.Add(p);
    public void RemovePlayer(Player p) => _players.Remove(p);
}

