// Singleton + Repository 結合實例
// 用 Singleton 管理 Repository 工廠

public sealed class RepositoryFactory
{
    private static readonly Lazy<RepositoryFactory> _instance =
        new Lazy<RepositoryFactory>(() => new RepositoryFactory());

    private readonly string _cs;

    private RepositoryFactory()
    {
        _cs = System.Configuration.ConfigurationManager
            .ConnectionStrings["AppDb"].ConnectionString;
    }

    public static RepositoryFactory Instance => _instance.Value;

    public IRepository<Employee> GetEmployeeRepository()
        => new EmployeeRepository(_cs);

    public IRepository<Order> GetOrderRepository()
        => new OrderRepository(_cs);
}

// 使用
var empRepo = RepositoryFactory.Instance.GetEmployeeRepository();
var emp = empRepo.GetById(1);

