public sealed class Logger
{
    // Lazy<T> 保證執行緒安全且延遲初始化
    private static readonly Lazy<Logger> _instance =
        new Lazy<Logger>(() => new Logger());

    // 私有建構子，防止外部 new Logger()
    private Logger() { }

    // 公開靜態存取點
    public static Logger Instance => _instance.Value;

    public void Log(string message)
    {
        string timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
        Console.WriteLine($"[{timestamp}] {message}");
    }
}

// 使用方式
Logger.Instance.Log("應用程式啟動");
Logger.Instance.Log("使用者登入");

public class Product
{
    public int    Id    { get; set; }
    public string Name  { get; set; }
    public decimal Price { get; set; }
}

public interface IProductRepository
{
    Product             GetById(int id);
    IEnumerable<Product> GetAll();
    void Add(Product product);
    void Delete(int id);
}

// 記憶體實作，用於單元測試（Mock）
public class InMemoryProductRepository : IProductRepository
{
    private readonly List<Product> _store = new List<Product>();

    public Product GetById(int id)
        => _store.FirstOrDefault(p => p.Id == id);

    public IEnumerable<Product> GetAll()
        => _store.AsReadOnly();

    public void Add(Product product)
    {
        if (_store.Any(p => p.Id == product.Id))
            throw new InvalidOperationException("ID 已存在");
        _store.Add(product);
    }

    public void Delete(int id)
    {
        var p = GetById(id);
        if (p != null) _store.Remove(p);
    }
}

