// 循序圖對應的 C# 呼叫鏈
// 對應「使用者登入」循序圖的程式碼結構

// LoginPage.aspx.cs（對應 LoginPage 參與者）
protected void btnLogin_Click(object sender, EventArgs e)
{
    var service = new AuthService();
    bool success = service.Validate(
        txtUsername.Text, txtPassword.Text);

    if (success)
        Response.Redirect("~/Dashboard.aspx");
    else
        lblError.Text = "帳號或密碼錯誤";
}

// AuthService.cs（對應 AuthService 參與者）
public class AuthService
{
    private readonly IUserRepository _repo;

    public AuthService() => _repo = new UserRepository();

    public bool Validate(string username, string password)
    {
        // 對應循序圖中 AuthService → UserDB 的訊息
        var user = _repo.GetByUsername(username);
        if (user == null) return false;

        // 自呼叫：驗證密碼邏輯
        return VerifyPassword(password, user.PasswordHash);
    }

    private bool VerifyPassword(string input, string hash)
        => BCrypt.Verify(input, hash);
}

