// 循序圖文字描述（由上到下，時間順序）：

// Customer ──點擊結帳──> ShoppingCart
// ShoppingCart ──PlaceOrder(items, userId)──> OrderService
// OrderService ──CheckStock(items)──> Database
// Database ──庫存結果──> OrderService
// [若庫存不足：OrderService ──錯誤訊息──> ShoppingCart ──顯示錯誤──> Customer]
// OrderService ──Charge(amount, cardInfo)──> PaymentGateway
// PaymentGateway ──付款結果──> OrderService
// [若付款失敗：OrderService ──付款失敗──> ShoppingCart ──> Customer]
// OrderService ──SaveOrder(order)──> Database
// Database ──orderId──> OrderService
// OrderService ──OrderResult(orderId)──> ShoppingCart
// ShoppingCart ──顯示訂單確認頁──> Customer

// 對應的 C# 呼叫鏈：
public class OrderService
{
    public OrderResult PlaceOrder(List<CartItem> items, int userId)
    {
        // 1. 檢查庫存
        if (!_db.CheckStock(items))
            return OrderResult.Fail("庫存不足");

        // 2. 呼叫金流
        var payResult = _payment.Charge(items.Sum(i => i.Total));
        if (!payResult.Success)
            return OrderResult.Fail("付款失敗");

        // 3. 儲存訂單
        int orderId = _db.SaveOrder(new Order(userId, items));
        return OrderResult.Ok(orderId);
    }
}

// 類別圖（Class Diagram）—— 靜態結構視角
// 描述：系統有哪些類別、類別有哪些屬性和方法、類別之間的關係
// 回答：「系統的結構是什麼？」
// 時間：設計階段，展示系統架構
// 範例：Customer 類別有 Name/Email，與 Order 是 1..* 關係

