// 三個測試層次：

// 1. 單元測試（Unit Test）
// 測試最小可測試單元（單一方法或類別）
// 隔離外部依賴（用 Mock 替換 DB、API）
// 執行最快，數量最多

// 2. 整合測試（Integration Test）
// 測試多個元件協同運作（如 Service + DB）
// 需要真實或測試用的外部資源
// 執行較慢

// 3. 使用者驗收測試（UAT - User Acceptance Test）
// 由客戶或終端使用者執行
// 驗證系統是否符合業務需求
// 上線前最後一道關卡

// MSTest Unit Test 範例：
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class CalculatorTests
{
    private Calculator _calc;

    [TestInitialize]
    public void Setup() => _calc = new Calculator();

    [TestMethod]
    public void Add_PositiveNumbers_ReturnsCorrectSum()
    {
        int result = _calc.Add(3, 5);
        Assert.AreEqual(8, result);
    }

    [TestMethod]
    public void Add_NegativeNumbers_ReturnsCorrectSum()
    {
        int result = _calc.Add(-3, -5);
        Assert.AreEqual(-8, result);
    }

    [TestMethod]
    public void Add_ZeroAndNumber_ReturnsNumber()
    {
        int result = _calc.Add(0, 7);
        Assert.AreEqual(7, result);
    }
}
